+  let db: Adapter;
+
+  const NS_A = 'user:alice';
+  const NS_B = 'user:bob';
+  const COL = '__ns';
+
+  beforeEach(() => {
+    baseAdapter = getBaseAdapter();
+    db = wrapWithRowLevelNamespace(baseAdapter, {
+      enabled: true,
+      columnName: COL,
+      mandatory: true,
+    });
+  });
+
